check.mjs.text:
#!/usr/bin/env node
// CLI: check a directory (or a list of files) of store-listing images against
// a store's published requirements, and exit non-zero when something would
// block the upload.
//
// Node 18+, no dependencies, no network. It reads the header bytes of the
// files you name and nothing else -- it never opens a socket, never sends an
// image anywhere, and never writes to the files it reads.
//
//   node check.mjs ./fastlane/screenshots/en-US
//   node check.mjs --store play ./play/listing
//   node check.mjs --store ios icon.png shot1.png shot2.png
//   node check.mjs ./screenshots --json
//
// Options:
//   --store ios|play   which store's requirements to check (default: ios)
//   --json             machine-readable report on stdout
//   --strict           exit 1 on notices too, not just danger findings
//
// Exit codes: 0 clean, 1 a finding would block the upload (or --strict and any
// finding at all), 2 the arguments or the files could not be used.

import { readFileSync, readdirSync, statSync } from 'node:fs';
import { join } from 'node:path';
import { classifyAssets, hasBlockingFinding, roleFromName } from './engine.mjs';
import { readImageInfo } from './image.mjs';
import { SPEC_REVIEWED, specFor } from './spec.mjs';

const IMAGE_EXT = /\.(png|jpe?g|heic|heif|webp|avif|gif|bmp|tiff?)$/i;

function collectFiles(paths) {
  const files = [];
  for (const p of paths) {
    let st;
    try {
      st = statSync(p);
    } catch {
      throw new Error(`cannot read "${p}": no such file or directory`);
    }
    if (st.isDirectory()) {
      // One level only. Store assets are conventionally flat per locale, and
      // recursing would sweep in an entire `fastlane/` tree of unrelated
      // metadata and report it as a mixed set.
      for (const entry of readdirSync(p).sort()) {
        const full = join(p, entry);
        try {
          if (statSync(full).isFile() && IMAGE_EXT.test(entry)) files.push(full);
        } catch {
          // A dangling symlink in an asset directory is not this tool's
          // problem, and refusing the whole run over one would be unhelpful.
        }
      }
    } else {
      files.push(p);
    }
  }
  return files;
}

function parseArgs(argv) {
  const opts = { store: 'ios', json: false, strict: false, paths: [] };
  for (let i = 0; i < argv.length; i += 1) {
    const arg = argv[i];
    if (arg === '--json') opts.json = true;
    else if (arg === '--strict') opts.strict = true;
    else if (arg === '--store') {
      opts.store = argv[i + 1];
      i += 1;
    } else if (arg.startsWith('--store=')) opts.store = arg.slice('--store='.length);
    else if (arg === '--help' || arg === '-h') opts.help = true;
    else if (arg.startsWith('-')) throw new Error(`unknown option "${arg}"`);
    else opts.paths.push(arg);
  }
  return opts;
}

const USAGE = `app-store-screenshot-check — validate store listing images before you upload

  node check.mjs [--store ios|play] [--json] [--strict] <dir-or-file>...

Checks pixel dimensions, image format, app-icon transparency, and whether a
screenshot set agrees with itself. Reads header bytes only; no network, no
upload, nothing written.`;

export function run(argv, { log = console.log, error = console.error } = {}) {
  let opts;
  try {
    opts = parseArgs(argv);
  } catch (e) {
    error(e.message);
    return 2;
  }
  if (opts.help) {
    log(USAGE);
    return 0;
  }
  if (opts.paths.length === 0) {
    error('give at least one directory or image file to check. --help for usage.');
    return 2;
  }

  let spec;
  try {
    spec = specFor(opts.store);
  } catch (e) {
    error(e.message);
    return 2;
  }

  let files;
  try {
    files = collectFiles(opts.paths);
  } catch (e) {
    error(e.message);
    return 2;
  }
  if (files.length === 0) {
    error('no image files found in the paths given.');
    return 2;
  }

  const assets = files.map((file) => {
    let info;
    try {
      info = readImageInfo(new Uint8Array(readFileSync(file)));
    } catch (e) {
      info = { format: 'unknown', error: `could not be opened: ${e.message}` };
    }
    return { name: file, role: roleFromName(file), info };
  });

  const report = classifyAssets(assets, { store: opts.store });

  if (opts.json) {
    log(JSON.stringify({ ...report, specReviewed: SPEC_REVIEWED, assets }, null, 2));
  } else {
    log(`${report.storeLabel} — ${files.length} file(s) checked`);
    log('');
    for (const a of assets) {
      const shape = a.info.error ? `unreadable (${a.info.error})` : `${a.info.format.toUpperCase()} ${a.info.width}x${a.info.height}`;
      log(`  ${a.role.padEnd(16)} ${shape.padEnd(28)} ${a.name}`);
    }
    log('');
    if (report.findings.length === 0) {
      log('No issues found against the rules this tool checks.');
    } else {
      for (const f of report.findings) {
        log(`${f.severity.toUpperCase()}: ${f.title}`);
        log(`  ${f.detail}`);
        log('');
      }
    }
    log(`Checked against: ${spec.source}`);
    log(`Size tables in this tool were last reviewed ${SPEC_REVIEWED}; the store's own current`);
    log('documentation is authoritative. This tool is not affiliated with Apple or Google.');
  }

  if (hasBlockingFinding(report)) return 1;
  if (opts.strict && report.findings.length > 0) return 1;
  return 0;
}

// `process.argv[1]` is this file only when it was run directly, so importing it
// from a test does not execute the CLI.
if (process.argv[1] && process.argv[1].endsWith('check.mjs')) {
  process.exit(run(process.argv.slice(2)));
}

engine.mjs.text:
// Classify a set of store-listing image assets against a store's published
// requirements. Pure: it takes already-measured asset descriptions and returns
// findings. Nothing here reads a file, touches a network, or knows whether it
// is running in Node or a browser tab.
//
// An asset is `{ name, role, info }` where `role` is 'screenshot', 'icon' or
// 'feature-graphic' and `info` is whatever `image.mjs` read out of the bytes.

import { matchIosScreenshotSize, specFor } from './spec.mjs';
import { orientationOf } from './image.mjs';

const DANGER = 'danger';
const NOTICE = 'notice';

const plural = (n, word) => `${n} ${word}${n === 1 ? '' : 's'}`;
const dim = (info) => `${info.width}x${info.height}`;

/**
 * Severity is a claim about consequence, not about how annoying something is,
 * and the distinction is the whole reason this tool is worth running in CI.
 *
 *   danger — the store is documented to reject this, or the set is internally
 *            inconsistent in a way no store accepts. Exits the CLI non-zero.
 *   notice — worth a look before you upload, but this tool is not certain the
 *            store will refuse it. Everything that depends on the size tables
 *            in `spec.mjs` lands here, because those tables can go stale and a
 *            check that fails a good build on a year-old table is worse than
 *            no check at all.
 */
function finding(id, severity, title, detail, assets = []) {
  return { id, severity, title, detail, assets };
}

function checkReadable(assets) {
  return assets
    .filter((a) => a.info?.error)
    .map((a) =>
      finding(
        'unreadable',
        DANGER,
        'File could not be measured',
        `"${a.name}" could not be read as an image this tool understands: ${a.info.error}. ` +
          `It was left out of every other check below, so treat this set as unverified until it is fixed.`,
        [a.name],
      ),
    );
}

function checkFormats(assets, spec) {
  const out = [];
  for (const a of assets) {
    // A HEIC or a WebP sets `error` (this tool cannot measure one) *and* has a
    // perfectly well-known format, and the format is the actionable half: "not
    // an accepted format, re-export it" tells the reader what to do, where
    // "could not be measured" reads like a bug in this tool. So the wrong
    // format is reported even though the file was unreadable -- only genuinely
    // unidentifiable bytes fall through to `unreadable` alone.
    if (a.info?.error && a.info.format === 'unknown') continue;
    const allowed =
      a.role === 'icon'
        ? spec.icon.allowedFormats
        : a.role === 'feature-graphic' && spec.featureGraphic
          ? spec.featureGraphic.allowedFormats
          : spec.acceptedFormats;
    if (!allowed.includes(a.info.format)) {
      out.push(
        finding(
          'unsupported-format',
          DANGER,
          `${a.info.format.toUpperCase()} is not an accepted format`,
          `"${a.name}" is a ${a.info.format.toUpperCase()} file. ${spec.storeLabel} accepts ` +
            `${allowed.map((f) => f.toUpperCase()).join(' or ')} for this asset. ` +
            (a.info.format === 'heic' || a.info.format === 'avif'
              ? 'This is the common one: renaming a screenshot to .png does not convert it, and the upload reads the bytes, not the name. Re-export it.'
              : 'Re-export it in an accepted format.'),
          [a.name],
        ),
      );
    }
  }
  return out;
}

function checkIcon(assets, spec) {
  const out = [];
  for (const a of assets.filter((x) => x.role === 'icon' && !x.info?.error)) {
    if (!spec.icon.allowTransparency && a.info.hasTransparency) {
      const why = a.info.hasAlphaChannel
        ? `its PNG colour type (${a.info.colorType}) declares an alpha channel`
        : 'it carries a tRNS transparency chunk';
      out.push(
        finding(
          'icon-transparency',
          DANGER,
          'App icon declares transparency',
          `"${a.name}" will be refused: ${why}. ${spec.storeLabel} requires a fully opaque app icon — ` +
            'this is the rejection that arrives at upload time, after the build and the archive. ' +
            'Flatten it onto an opaque background and re-export (exporting as JPEG also removes the ' +
            'alpha channel, since JPEG has none). Do not paint the rounded corners yourself; the store ' +
            'masks them for you.',
          [a.name],
        ),
      );
    }
    if (a.info.width !== spec.icon.width || a.info.height !== spec.icon.height) {
      out.push(
        finding(
          'icon-dimensions',
          DANGER,
          'App icon is the wrong size',
          `"${a.name}" is ${dim(a.info)}. ${spec.storeLabel} requires exactly ` +
            `${spec.icon.width}x${spec.icon.height}.`,
          [a.name],
        ),
      );
    }
    if (a.info.format === 'png' && a.info.interlaced) {
      out.push(
        finding(
          'icon-interlaced',
          NOTICE,
          'App icon is an interlaced PNG',
          `"${a.name}" is stored interlaced (Adam7). Store asset pipelines are documented to want a ` +
            'standard non-interlaced PNG, and interlacing buys nothing for an image the store ' +
            'already serves at a fixed size. Re-export with interlacing off.',
          [a.name],
        ),
      );
    }
    if (a.info.format === 'png' && a.info.bitDepth > 8) {
      out.push(
        finding(
          'icon-bit-depth',
          NOTICE,
          'App icon is deeper than 8 bits per channel',
          `"${a.name}" is ${a.info.bitDepth}-bit per channel. Store icons are expected at 8 bits; ` +
            'a 16-bit export is several times larger for no visible difference and some pipelines ' +
            'reject it outright.',
          [a.name],
        ),
      );
    }
  }
  return out;
}

function checkFeatureGraphic(assets, spec) {
  if (!spec.featureGraphic) return [];
  const out = [];
  for (const a of assets.filter((x) => x.role === 'feature-graphic' && !x.info?.error)) {
    const { width, height } = spec.featureGraphic;
    if (a.info.width !== width || a.info.height !== height) {
      out.push(
        finding(
          'feature-graphic-dimensions',
          DANGER,
          'Feature graphic is the wrong size',
          `"${a.name}" is ${dim(a.info)}. ${spec.storeLabel} requires exactly ${width}x${height}.`,
          [a.name],
        ),
      );
    }
    if (!spec.featureGraphic.allowTransparency && a.info.hasTransparency) {
      out.push(
        finding(
          'feature-graphic-transparency',
          DANGER,
          'Feature graphic declares transparency',
          `"${a.name}" declares transparency. ${spec.storeLabel} requires an opaque feature graphic; ` +
            'anything transparent composites against a background you do not control.',
          [a.name],
        ),
      );
    }
  }
  return out;
}

/**
 * The check that needs no specification at all, and the one most likely to
 * catch a real mistake: a screenshot set whose members disagree with each
 * other. Regenerating four of five screenshots on a newer simulator is the
 * ordinary way a set ends up mixed, and it is invisible in a file listing.
 */
function checkSetConsistency(shots) {
  const out = [];
  const usable = shots.filter((s) => !s.info?.error);
  if (usable.length < 2) return out;

  const sizes = new Map();
  for (const s of usable) {
    const key = dim(s.info);
    if (!sizes.has(key)) sizes.set(key, []);
    sizes.get(key).push(s.name);
  }
  if (sizes.size > 1) {
    const summary = [...sizes.entries()]
      .map(([size, names]) => `${size} (${names.join(', ')})`)
      .join('; ');
    out.push(
      finding(
        'mixed-dimensions',
        DANGER,
        'Screenshots in this set are not all the same size',
        `This set mixes ${sizes.size} different pixel sizes: ${summary}. A screenshot set uploaded ` +
          'for one display class has to be internally consistent — the usual cause is regenerating ' +
          'some of the set on a different simulator or device and keeping the rest.',
        usable.map((s) => s.name),
      ),
    );
  }

  const orientations = new Set(usable.map((s) => orientationOf(s.info)));
  if (orientations.size > 1) {
    out.push(
      finding(
        'mixed-orientation',
        NOTICE,
        'Screenshots in this set mix portrait and landscape',
        `This set contains ${[...orientations].join(' and ')} images. Stores treat portrait and ` +
          'landscape as separate sets; uploading them together is usually an accident, and where it ' +
          'is deliberate the two halves belong in their own sets.',
        usable.map((s) => s.name),
      ),
    );
  }
  return out;
}

function checkCount(shots, spec) {
  const out = [];
  if (shots.length === 0) return out;
  if (shots.length > spec.maxScreenshotsPerSet) {
    out.push(
      finding(
        'too-many-screenshots',
        DANGER,
        'More screenshots than the store accepts',
        `This set has ${plural(shots.length, 'screenshot')}. ${spec.storeLabel} accepts at most ` +
          `${spec.maxScreenshotsPerSet} per set, so the upload will refuse the extras.`,
      ),
    );
  }
  if (shots.length < spec.minScreenshotsPerSet) {
    out.push(
      finding(
        'too-few-screenshots',
        NOTICE,
        'Fewer screenshots than the store requires',
        `This set has ${plural(shots.length, 'screenshot')}. ${spec.storeLabel} requires at least ` +
          `${spec.minScreenshotsPerSet}, so the listing cannot be submitted as it stands.`,
      ),
    );
  }
  return out;
}

function checkIosScreenshotSizes(shots) {
  const out = [];
  for (const s of shots.filter((x) => !x.info?.error)) {
    if (!matchIosScreenshotSize(s.info.width, s.info.height)) {
      out.push(
        finding(
          'unrecognised-size',
          NOTICE,
          'Screenshot size matches no display class this tool knows',
          `"${s.name}" is ${dim(s.info)}, which is not in this tool's table of App Store display ` +
            'classes. That is a reason to check, not a verdict: Apple adds and retires device ' +
            'classes, and the table here is a transcription that can fall behind. Confirm the size ' +
            "against App Store Connect's current screenshot specifications before changing anything.",
          [s.name],
        ),
      );
    }
  }
  return out;
}

function checkPlayScreenshotBounds(shots, spec) {
  const out = [];
  const { minSide, maxSide, maxAspectRatio } = spec.screenshot;
  for (const s of shots.filter((x) => !x.info?.error)) {
    const short = Math.min(s.info.width, s.info.height);
    const long = Math.max(s.info.width, s.info.height);
    if (short < minSide || long > maxSide) {
      out.push(
        finding(
          'screenshot-out-of-bounds',
          DANGER,
          'Screenshot is outside the accepted size range',
          `"${s.name}" is ${dim(s.info)}. ${spec.storeLabel} requires each side between ` +
            `${minSide} and ${maxSide} pixels.`,
          [s.name],
        ),
      );
    }
    const ratio = long / short;
    if (ratio > maxAspectRatio + 1e-9) {
      out.push(
        finding(
          'screenshot-aspect-ratio',
          DANGER,
          'Screenshot is too elongated',
          `"${s.name}" is ${dim(s.info)}, an aspect ratio of ${ratio.toFixed(2)}:1. ` +
            `${spec.storeLabel} accepts at most ${maxAspectRatio}:1. A tall-phone screenshot that ` +
            'has been padded or stitched is the usual cause.',
          [s.name],
        ),
      );
    }
  }
  return out;
}

/**
 * Check one set of assets against one store.
 *
 * `assets`: `[{ name, role, info }]`. Roles other than 'icon' and
 * 'feature-graphic' are treated as screenshots, since that is what an
 * unlabelled file dropped on the page almost always is.
 */
export function classifyAssets(assets, { store = 'ios' } = {}) {
  const spec = specFor(store);
  const list = (assets || []).map((a) => ({ ...a, role: a.role || 'screenshot' }));
  const shots = list.filter((a) => a.role === 'screenshot');

  const findings = [
    ...checkReadable(list),
    ...checkFormats(list, spec),
    ...checkIcon(list, spec),
    ...checkFeatureGraphic(list, spec),
    ...checkCount(shots, spec),
    ...checkSetConsistency(shots),
    ...(spec.store === 'ios' ? checkIosScreenshotSizes(shots) : checkPlayScreenshotBounds(shots, spec)),
  ];

  // Stable ordering: danger first, then by the order the checks above run, so
  // a CI log diffs cleanly between runs and the thing that blocks the upload
  // is the thing at the top.
  const rank = (f) => (f.severity === DANGER ? 0 : 1);
  findings.sort((a, b) => rank(a) - rank(b));

  return {
    store: spec.store,
    storeLabel: spec.storeLabel,
    source: spec.source,
    counts: {
      assets: list.length,
      screenshots: shots.length,
      danger: findings.filter((f) => f.severity === DANGER).length,
      notice: findings.filter((f) => f.severity === NOTICE).length,
    },
    findings,
  };
}

/** True when anything found would block the upload. Drives the CLI exit code. */
export const hasBlockingFinding = (report) => report.findings.some((f) => f.severity === DANGER);

/**
 * Guess an asset's role from its filename, so a directory of files can be
 * checked without labelling every one by hand. Deliberately conservative:
 * anything not obviously an icon or a feature graphic is a screenshot, which
 * is the role with the least severe checks, so a wrong guess under-reports
 * rather than inventing a failure.
 */
export function roleFromName(name) {
  const base = String(name).toLowerCase().replace(/\\/g, '/').split('/').pop();
  if (/feature[-_ ]?graphic/.test(base)) return 'feature-graphic';
  // `ic_launcher-playstore.png` is what Android Studio names the Play Store
  // icon it generates, so it is the single most likely filename to arrive as
  // a Play icon and is worth matching by name rather than by the word "icon".
  if (/^ic_launcher([-_.]|$)/.test(base)) return 'icon';
  // "icon" has to stand alone as a word: otherwise `iconic-view.png` gets the
  // strictest checks in the tool applied to an ordinary screenshot.
  if (/(^|[-_ ])(app)?icon([-_ ]|\.|$)/.test(base)) return 'icon';
  return 'screenshot';
}

image.mjs.text:
// Read an image's shape out of its own header bytes -- format, pixel
// dimensions, bit depth, whether it carries an alpha channel, and whether a
// PNG is interlaced -- with no dependencies and without decoding a single
// pixel.
//
// WHY IT PARSES HEADERS RATHER THAN DECODING
//
// Every property this tool checks lives in the first few dozen bytes of the
// file. Decoding would mean either a native image library (so: an install
// step, and a CLI that cannot be dropped into a CI job as three files) or
// `<canvas>` in the browser -- and canvas is the wrong instrument twice over.
// It cannot tell an opaque RGBA image from an RGB one, because it hands back
// RGBA either way, and "does this PNG declare an alpha channel?" is exactly
// the question App Store Connect asks of an app icon. The declaration is in
// the IHDR colour type, not in the pixels, so the header is not an
// approximation of the answer here -- it *is* the answer.
//
// Everything below works on a Uint8Array, so the same code runs against
// `fs.readFileSync` in the CLI and a `File.arrayBuffer()` in the browser.

/** Formats a store will accept, and the ones that get mistaken for them. */
const SIGNATURES = [
  { format: 'png', bytes: [0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a] },
  { format: 'gif', bytes: [0x47, 0x49, 0x46, 0x38] },
  { format: 'bmp', bytes: [0x42, 0x4d] },
  { format: 'tiff', bytes: [0x49, 0x49, 0x2a, 0x00] },
  { format: 'tiff', bytes: [0x4d, 0x4d, 0x00, 0x2a] },
  { format: 'pdf', bytes: [0x25, 0x50, 0x44, 0x46] },
];

const startsWith = (bytes, sig, offset = 0) =>
  sig.every((b, i) => bytes[offset + i] === b);

const ascii = (bytes, offset, length) => {
  let out = '';
  for (let i = 0; i < length; i += 1) out += String.fromCharCode(bytes[offset + i] ?? 0);
  return out;
};

const u32be = (bytes, offset) =>
  ((bytes[offset] << 24) >>> 0) + (bytes[offset + 1] << 16) + (bytes[offset + 2] << 8) + bytes[offset + 3];

const u16be = (bytes, offset) => (bytes[offset] << 8) + bytes[offset + 1];

/**
 * Detect the container format from magic bytes alone.
 *
 * The filename extension is deliberately not consulted. A `.png` that is
 * really a HEIC (the single most common way a macOS or iPhone screenshot
 * reaches an upload as the wrong format -- Preview and Photos will happily
 * rename without converting) has to be caught by its bytes, because the name
 * is precisely the thing that lied.
 */
export function detectFormat(bytes) {
  if (!bytes || bytes.length < 12) return 'unknown';
  for (const { format, bytes: sig } of SIGNATURES) {
    if (startsWith(bytes, sig)) return format;
  }
  // JPEG: SOI marker, then any number of segments.
  if (bytes[0] === 0xff && bytes[1] === 0xd8 && bytes[2] === 0xff) return 'jpeg';
  // ISO base media file format: a `ftyp` box whose brand names the flavour.
  if (ascii(bytes, 4, 4) === 'ftyp') {
    const brand = ascii(bytes, 8, 4);
    if (/^(heic|heix|hevc|hevx|mif1|msf1|heim|heis|hevm|hevs)$/.test(brand)) return 'heic';
    if (brand === 'avif' || brand === 'avis') return 'avif';
    return 'iso-media';
  }
  // WebP: RIFF container with a WEBP fourcc.
  if (ascii(bytes, 0, 4) === 'RIFF' && ascii(bytes, 8, 4) === 'WEBP') return 'webp';
  return 'unknown';
}

/**
 * PNG. Dimensions, bit depth, colour type and interlace all live in IHDR,
 * which the spec requires to be the first chunk; `tRNS` may appear later and
 * adds transparency to a colour type that has no alpha channel of its own,
 * which App Store Connect counts as transparency just the same.
 */
function readPng(bytes) {
  if (bytes.length < 33) return { error: 'truncated PNG: no IHDR' };
  if (ascii(bytes, 12, 4) !== 'IHDR') return { error: 'malformed PNG: first chunk is not IHDR' };

  const colorType = bytes[25];
  const info = {
    format: 'png',
    width: u32be(bytes, 16),
    height: u32be(bytes, 20),
    bitDepth: bytes[24],
    colorType,
    // Colour type 4 is greyscale+alpha, 6 is truecolour+alpha. Types 0, 2 and
    // 3 have no alpha channel -- but 3 (palette) and the others can still be
    // made transparent by a tRNS chunk, handled below.
    hasAlphaChannel: colorType === 4 || colorType === 6,
    interlaced: bytes[28] === 1,
    hasTransparencyChunk: false,
  };

  // Walk the chunk list for tRNS. Stop at IDAT: anything after the first image
  // data chunk cannot be a tRNS (the spec requires tRNS to precede IDAT), and
  // walking a multi-megabyte IDAT run buys nothing.
  let offset = 8;
  while (offset + 8 <= bytes.length) {
    const length = u32be(bytes, offset);
    const type = ascii(bytes, offset + 4, 4);
    if (type === 'tRNS') {
      info.hasTransparencyChunk = true;
      break;
    }
    if (type === 'IDAT' || type === 'IEND') break;
    // A corrupt length would otherwise spin or run off the end.
    if (!Number.isFinite(length) || length < 0) break;
    offset += 12 + length;
  }

  info.hasTransparency = info.hasAlphaChannel || info.hasTransparencyChunk;
  return info;
}

/**
 * JPEG. Dimensions live in whichever Start Of Frame marker the encoder used,
 * so the segment list has to be walked rather than read at a fixed offset.
 * JPEG has no alpha channel in any baseline or progressive form, which is
 * itself a useful fact: "convert it to JPEG" is the standard fix for an icon
 * rejected for transparency.
 */
function readJpeg(bytes) {
  let offset = 2;
  while (offset + 4 <= bytes.length) {
    if (bytes[offset] !== 0xff) {
      offset += 1; // Resynchronise over fill bytes rather than giving up.
      continue;
    }
    const marker = bytes[offset + 1];
    // Standalone markers: no length field follows, so do not try to skip one.
    if (marker === 0xd8 || marker === 0x01 || (marker >= 0xd0 && marker <= 0xd7)) {
      offset += 2;
      continue;
    }
    if (marker === 0xd9 || marker === 0xda) break; // EOI, or start of scan.
    const length = u16be(bytes, offset + 2);
    // SOF0/1/2/3, SOF5-7, SOF9-11, SOF13-15 all carry the frame header.
    // C4 (DHT), C8 (reserved) and CC (DAC) share the range but are not frames.
    const isSof =
      marker >= 0xc0 && marker <= 0xcf && marker !== 0xc4 && marker !== 0xc8 && marker !== 0xcc;
    if (isSof) {
      return {
        format: 'jpeg',
        height: u16be(bytes, offset + 5),
        width: u16be(bytes, offset + 7),
        bitDepth: bytes[offset + 4],
        components: bytes[offset + 9],
        progressive: marker === 0xc2,
        hasAlphaChannel: false,
        hasTransparencyChunk: false,
        hasTransparency: false,
      };
    }
    if (length < 2) break; // Corrupt: a segment cannot be shorter than its own length field.
    offset += 2 + length;
  }
  return { error: 'malformed JPEG: no Start Of Frame segment found' };
}

/**
 * Read what can be known about an image from its header bytes.
 *
 * Returns `{ format, width, height, ... }` on success, or `{ format, error }`
 * when the bytes are not a format this can measure. An unreadable file is
 * reported, never guessed at: a caller that cannot see the dimensions must be
 * told so rather than handed a zero it might compare against a spec.
 */
export function readImageInfo(bytes) {
  const format = detectFormat(bytes);
  if (format === 'png') return readPng(bytes);
  if (format === 'jpeg') return readJpeg(bytes);
  return {
    format,
    error:
      format === 'unknown'
        ? 'unrecognised image format (not PNG or JPEG)'
        : `${format.toUpperCase()} dimensions are not readable without decoding; this tool measures PNG and JPEG`,
  };
}

/** Portrait, landscape, or square -- the shape a store groups a set by. */
export function orientationOf({ width, height }) {
  if (!width || !height) return 'unknown';
  if (width === height) return 'square';
  return width > height ? 'landscape' : 'portrait';
}

